function validate([votes]) {
  if (!Array.isArray(votes) || votes.length < 1 || votes.length > 1000) return 'votes needs 1 to 1000 ballots.';
  const first = votes[0];
  if (typeof first !== 'string' || first.length < 1 || first.length > 26) return 'Each ballot has 1 to 26 teams.';
  if (!/^[A-Z]+$/.test(first)) return 'Teams are uppercase letters A to Z.';
  if (new Set(first).size !== first.length) return 'A ballot may not list a team twice.';
  const sorted = first.split('').sort().join('');
  for (const vote of votes) {
    if (typeof vote !== 'string' || vote.length !== first.length) return 'All ballots must have the same length.';
    if (vote.split('').sort().join('') !== sorted) return 'Every ballot must list the same teams, each once.';
  }
  return null;
}

