function rankTeams(votes) {
  const teams = votes[0].split('');
  const width = teams.length;
  const tally = new Map();
  for (const team of teams) {
    tally.set(team, new Array(width).fill(0));
  }
  for (const vote of votes) {
    for (let pos = 0; pos < width; pos++) {
      tally.get(vote[pos])[pos]++;
    }
  }
  teams.sort((a, b) => {
    for (let pos = 0; pos < width; pos++) {
      const diff = tally.get(b)[pos] - tally.get(a)[pos];
      if (diff !== 0) {
        return diff;
      }
    }
    return a < b ? -1 : 1;
  });
  return teams.join('');
}

