function rankTeams(votes) {
  // Give each team a fixed-width key: (9999 - votes at each position), then its letter.
  // Plain string order on these keys is exactly the ranking order.
  const letters = [...new Set(votes.join(''))];
  const keyed = letters.map(team => {
    let key = '';
    for (let pos = 0; pos < votes[0].length; pos++) {
      let got = 0;
      for (const vote of votes) if (vote[pos] === team) got++;
      key += String(9999 - got).padStart(4, '0');
    }
    return key + team;
  });
  keyed.sort();
  return keyed.map(key => key[key.length - 1]).join('');
}

