function generate(rand, size) {
  const large = size === 'large';
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
  const shuffle = list => {
    const copy = list.slice();
    for (let i = copy.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [copy[i], copy[j]] = [copy[j], copy[i]];
    }
    return copy;
  };
  const width = large ? 20 + Math.floor(rand() * 7) : 1 + Math.floor(rand() * 6);
  const teams = shuffle(alphabet).slice(0, width);
  const mode = Math.floor(rand() * 3);
  const votes = [];
  if (mode === 2) {
    // Every rotation of one order, the same number of times: all teams tie, so the answer is alphabetical.
    const rounds = large ? Math.floor(700 / width) : 1 + Math.floor(rand() * 2);
    for (let r = 0; r < rounds; r++)
      for (let k = 0; k < width; k++) votes.push(teams.slice(k).concat(teams.slice(0, k)).join(''));
    // Small inputs sometimes add one extra ballot to break the tie.
    if (!large && rand() < 0.5) votes.push(shuffle(teams).join(''));
    return [shuffle(votes)];
  }
  const count = large ? 500 + Math.floor(rand() * 201) : 1 + Math.floor(rand() * 8);
  // Mode 1 reuses a few ballots so many teams tie on the early positions.
  const templates = Array.from({ length: 2 + Math.floor(rand() * 3) }, () => shuffle(teams).join(''));
  for (let i = 0; i < count; i++) {
    votes.push(mode === 0 ? shuffle(teams).join('') : templates[Math.floor(rand() * templates.length)]);
  }
  return [votes];
}
